# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs, factor=2):
    return [v * factor for v in xs[1:]]

# region: gather
def gather(xs, offset=4):
    return [v + offset for v in xs]

# region: emit
def emit(xs, factor=2):
    return [v * factor for v in xs]

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(render(emit(gather(fold(sift(raw))))))

